  document.addEventListener("click",e=>{const cancel=e.target.closest("[data-cancel-collection]");if(cancel){e.preventDefault();e.stopImmediatePropagation();const reason=prompt("سبب الإلغاء المحاسبي:");if(reason?.trim())runCommand("document.cancel",{collection:cancel.dataset.cancelCollection,id:cancel.dataset.cancelId,date:new Date().toISOString().slice(0,10),reason},"تم عكس المستند وإلغاؤه").catch(()=>{});return}const approval=e.target.closest("[data-approve-id]");if(approval){e.preventDefault();e.stopImmediatePropagation();if(confirm("سيتم اعتماد الطلب وتنفيذ أثره المحاسبي. متابعة؟"))runCommand("approval.approve",{approvalId:approval.dataset.approveId},"تم اعتماد الطلب وتنفيذه").catch(()=>{});return}const action=e.target.closest("[data-action]");if(action&&(financialAction(action.dataset.action)||procurementAction(action.dataset.action)||treasuryAction(action.dataset.action)||staffExpenseUploadAction(action.dataset.action)||staffFinanceAction(action.dataset.action)||operationsAction(action.dataset.action)||lifecycleAction(action.dataset.action))){e.preventDefault();e.stopImmediatePropagation()}},true)
