  document.addEventListener("submit",async e=>{if(e.target.id!=="staffExpenseUploadForm")return;e.preventDefault();e.stopImmediatePropagation();const button=e.target.querySelector("button"),f=new FormData(e.target),file=f.get("invoiceFile");if(!(file instanceof File)||!file.size)return toast("صورة الفاتورة إلزامية");button.disabled=true;try{const bytes=new Uint8Array(await file.arrayBuffer());let binary="";for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const uploaded=await window.V2Persistence.command("document.upload",{name:file.name,mimeType:file.type,base64:btoa(binary),category:"staff-expense"});db=uploaded.data||db;const taxEnabled=f.get("taxEnabled")==="true",expense=await window.V2Persistence.command("staff-expense.create",{staffId:f.get("staffId"),description:f.get("description"),date:f.get("date"),net:num(f.get("net")),taxEnabled,taxRate:taxEnabled?15:0,attachmentId:uploaded.result.record.id});db=expense.data||db;localStorage.setItem(DATA_KEY,JSON.stringify(db));closeModal();render();toast("تم رفع الفاتورة وترحيل المصروف")}catch(error){button.disabled=false;toast(error.message||"تعذر حفظ مصروف الموظف")}},true)
